from pathlib import Path
import json,re,html
root=Path(__file__).resolve().parents[1]
out=root/'public/pvhs55'
cal=json.loads((root/'curriculum/pvhs55/calendar-basis.json').read_text())
style='body{font:17px/1.6 Arial,sans-serif;color:#17202a;max-width:1100px;margin:32px auto;padding:24px}a{color:#075b88}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccd4dc;padding:10px;text-align:left}th{background:#edf2f6}.notice{padding:16px;border-left:5px solid #a97100;background:#fff4dc}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px}.card{padding:20px;border:1px solid #ccd4dc;border-radius:8px}@media print{body{font-size:11pt}tr{break-inside:avoid}}'
def page(title,body):return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{style}</style></head><body>{body}</body></html>'
cards=''.join(f'<article class="card"><h2>WLD {n}</h2><p>{title}</p><p>{minutes} minutes • 55 instructional days</p><a href="WLD{n}-55-Day-Instructor-Planner.html">Open instructor planner and forms</a></article>' for n,title,minutes in [(114,'CNC Plasma Operations',60),(115,'Introduction to GMAW/FCAW/GTAW',120),(120,'Capstone Fabrication',60),(150,'Advanced Processes',120)])
body=f'''<a href="/planner">Return to LTG planner</a><h1>PVHS Level I instructor planners</h1><p>Cohorts B and C • 2026–27 • Published edition: October 28, 2026</p>
<p><strong>WLD 114/115:</strong> December 21, 2026–March 22, 2027.<br><strong>WLD 120/150:</strong> March 23–June 16, 2027.</p>
<p><a href="calendar.html">Full 110-day calendar and exceptions</a> · <a href="/signoffs">Instructor safety and QC signoffs</a></p>
<div class="notice">Early-dismissal and exam days count as instructional days in this authorized schedule. Actual available minutes still need confirmation. Adjust the daily teaching plan to the available time and record actual delivery; a scheduled day does not establish attendance, completed hours or competency.</div>
<div class="cards">{cards}</div>
<h2>Daily instructor workflow</h2><ol><li>Select the correct cohort and course section in LTG. Each cohort has separate enrollment, attendance, grades and notes.</li><li>Open the scheduled lesson. Check objectives, equipment, safety, daily timing and required evidence before instruction.</li><li>Verify student enrollment and individual authorization before machine work. Record CNC authorization for the exact machine and operation.</li><li>For WLD 120, record QC reviews at Day 20 (April 27), Day 30 (May 11) and Day 40 (May 25), using the same job and drawing revision. A hold or revocation requires downstream work to be reviewed again.</li><li>For WLD 150, retain every bend-test attempt and record the observed result at Day 31 (May 12). A failed or invalid result cannot release the checkpoint.</li><li>Grade only observed work with supporting evidence and a rubric. Leave pending assessments unscored. Record lesson notes and actual delivery separately from student grades or signoffs.</li></ol>
<h2>Paired daily blocks</h2><table><thead><tr><th>Cohort</th><th>WLD 114 or 120</th><th>WLD 115 or 150</th></tr></thead><tbody><tr><td>B</td><td>8:30–9:30 a.m.</td><td>9:30–11:30 a.m.</td></tr><tr><td>C</td><td>11:30 a.m.–12:30 p.m.</td><td>12:30–2:30 p.m.</td></tr></tbody></table>
<h2>Source and release notes</h2><p>The four shared lesson masters preserve the supplied 55-day sequence. The existing approved LTG syllabi remain the curriculum authority. Existing night guides and WLD 105/110 classes remain in place. No student enrollment or grades were copied into the new sections.</p><p>Outstanding source differences: WLD 114's supplied syllabus lists 2 credits while an archive lists 1; WLD 150 has archival description/corequisite labeling errors; the official night WLD 120/150 calendar remains unresolved (23 reported versus 24 archived meetings). This release does not change registrar credits or night schedules. The earlier planner chat has not been recovered; authored rubric details remain identified in each planner.</p><p>Before instruction, verify installed-machine procedures, authorized Academy access and local acceptance criteria. Browser-based signed-in visual checks remain pending; database and automated workflow checks are recorded separately.</p>'''
(out/'index.html').write_text(page('PVHS 55-day instructor planners',body),encoding='utf-8')
rows=''.join('<tr>'+''.join('<td>'+html.escape(str(r[k]))+'</td>' for k in ['pair','instructional_day','proposed_date','weekday','calendar_flag','checkpoint'])+'</tr>' for r in cal['rows'])
(out/'calendar.html').write_text(page('PVHS 2026–27 course calendar',f'<a href="index.html">Instructor planners</a><h1>PVHS 2026–27 course calendar</h1><p>Dates authorized October 28, 2026, using the supplied PVHS academic calendar and December 21 start. Both cohorts use the same 55 dates per course pair.</p><p class="notice">Early-dismissal and exam-day minutes require confirmation. Weather and emergency changes may require rescheduling. No hours, attendance or grades are inferred from these dates.</p><table><thead><tr><th>Course pair</th><th>Day</th><th>Date</th><th>Weekday</th><th>Calendar exception</th><th>Checkpoint</th></tr></thead><tbody>{rows}</tbody></table>'),encoding='utf-8')
for p in out.glob('WLD*.html'):
    t=p.read_text(encoding='utf-8')
    t=t.replace('PVHS Level I • Instructor review edition','PVHS Level I • Instructor edition')
    t=t.replace('PVHS-55-2026-10-27-review.1 • Prepared 27 October 2026 • Undated master content','PVHS-55-2026-10-28-live.1 • Published 28 October 2026 • Scheduled dates authorized')
    t=t.replace('Source conflicts and the unpublished night calendar remain open; production and existing student records remain unchanged. A separate staging review import is held pending verification.','The source notes and night-calendar differences remain documented. Live publication and dates are authorized; existing student records are preserved.')
    t=t.replace('Planning only. LTG dates remain unset. Original master planners are unchanged.','Scheduled dates authorized October 28, 2026. Daily lesson content is preserved.')
    t=t.replace('href="../PROPOSED-CALENDAR.html"','href="calendar.html"').replace('href="../index.html"','href="index.html"')
    t=t.replace('href="PROPOSED-CALENDAR.html"','href="calendar.html"')
    t=re.sub(r'<a href="\.\./WLD\d+-55-Day-Instructor-Planner.html">.*?</a>','<a href="index.html">All planners</a>',t)
    t=t.replace('href="../INSTRUCTOR-START-HERE.html"','href="index.html"')
    t=t.replace('PROPOSED CALENDAR REVIEW COPY','AUTHORIZED COURSE SCHEDULE')
    t=t.replace('Dates are not finalized. Early-dismissal/exam days are provisional meeting days.','Dates authorized for live use October 28, 2026. Early-dismissal/exam days count as meetings; available minutes remain unconfirmed.')
    p.write_text(t,encoding='utf-8')
print('Published-page bundle: 4 planners, calendar and instructor start page')
